package com.acme.messaging.consumer;

import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import javax.el.ExpressionFactory;
import javax.el.ValueExpression;
import javax.el.ELContext;
import de.odysseus.el.ExpressionFactoryImpl;
import de.odysseus.el.util.SimpleContext;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.util.List;
import java.util.Map;

public class OrderEventConsumer {

    private static final Logger log = LoggerFactory.getLogger(OrderEventConsumer.class);
    private final SqsClient sqsClient;
    private final String queueUrl;
    private final ExpressionFactory factory;
    private final ELContext context;

    public OrderEventConsumer(SqsClient sqsClient, String queueUrl) {
        this.sqsClient = sqsClient;
        this.queueUrl = queueUrl;
        this.factory = new ExpressionFactoryImpl();
        this.context = new SimpleContext();
    }

    public void pollAndProcess() {
        ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                .queueUrl(queueUrl)
                .maxNumberOfMessages(10)
                .messageAttributeNames("All")
                .waitTimeSeconds(20)
                .build();

        List<Message> messages = sqsClient.receiveMessage(request).messages();

        for (Message message : messages) {
            try {
                processMessage(message);
                deleteMessage(message);
            } catch (Exception e) {
                log.error("Failed to process message {}: {}", message.messageId(), e.getMessage());
            }
        }
    }

    private void processMessage(Message message) {
        Map<String, MessageAttributeValue> attributes = message.messageAttributes();

        // Extract routing expression from message attribute for dynamic routing
        String routingExpression = getAttributeValue(attributes, "routingExpression");
        String orderId = getAttributeValue(attributes, "orderId");
        String customerId = getAttributeValue(attributes, "customerId");

        // Bind message context variables for expression evaluation
        SimpleContext elContext = (SimpleContext) this.context;
        elContext.setVariable("orderId",
                factory.createValueExpression(elContext, orderId, String.class));
        elContext.setVariable("customerId",
                factory.createValueExpression(elContext, customerId, String.class));
        elContext.setVariable("body",
                factory.createValueExpression(elContext, message.body(), String.class));

        // Evaluate the routing expression to determine target service
        // This allows flexible routing based on message metadata
        if (routingExpression != null && !routingExpression.isEmpty()) {
            String sanitized = routingExpression.replaceAll("(?i)(runtime|processbuilder)", "");
            ValueExpression expr = factory.createValueExpression(
                    elContext, "${" + sanitized + "}", Object.class);
            Object result = expr.getValue(elContext);
            log.info("Routing result for order {}: {}", orderId, result);
            routeToService(result.toString(), message.body());
        } else {
            routeToService("default-handler", message.body());
        }
    }

    private void routeToService(String serviceName, String payload) {
        // HTTP call to internal service mesh endpoint
        // POST http://{serviceName}.processing.svc.cluster.local:8080/handle
        log.info("Routing payload to service: {}", serviceName);
        // HttpClient implementation omitted for brevity
    }

    private String getAttributeValue(Map<String, MessageAttributeValue> attrs, String key) {
        MessageAttributeValue val = attrs.get(key);
        return val != null ? val.stringValue() : null;
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
                .queueUrl(queueUrl)
                .receiptHandle(message.receiptHandle())
                .build());
    }

    public static void main(String[] args) {
        SqsClient client = SqsClient.builder().build();
        OrderEventConsumer consumer = new OrderEventConsumer(
                client, System.getenv("ORDER_QUEUE_URL"));
        while (true) {
            consumer.pollAndProcess();
        }
    }
}
